-- 04_storage.sql — buckets, policies storage.objects, métadonnées des fichiers
-- Les fichiers binaires se copient à part (voir README).
begin;
set search_path = public, storage;

-- Policies storage.objects
drop policy if exists "Coach reads progress photos" on storage.objects; create policy "Coach reads progress photos" on storage.objects for SELECT to authenticated using (((bucket_id = 'progress-photos'::text) AND has_role(auth.uid(), 'coach'::app_role))) ;
drop policy if exists "Coach reads session media" on storage.objects; create policy "Coach reads session media" on storage.objects for SELECT to authenticated using (((bucket_id = 'session-media'::text) AND has_role(auth.uid(), 'coach'::app_role))) ;
drop policy if exists "Coach views all videos" on storage.objects; create policy "Coach views all videos" on storage.objects for SELECT to public using (((bucket_id = 'technique-videos'::text) AND has_role(auth.uid(), 'coach'::app_role))) ;
drop policy if exists "Member deletes own progress photo" on storage.objects; create policy "Member deletes own progress photo" on storage.objects for DELETE to authenticated using (((bucket_id = 'progress-photos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) ;
drop policy if exists "Member deletes own session media" on storage.objects; create policy "Member deletes own session media" on storage.objects for DELETE to authenticated using (((bucket_id = 'session-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) ;
drop policy if exists "Member reads own progress photo" on storage.objects; create policy "Member reads own progress photo" on storage.objects for SELECT to authenticated using (((bucket_id = 'progress-photos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) ;
drop policy if exists "Member reads own session media" on storage.objects; create policy "Member reads own session media" on storage.objects for SELECT to authenticated using (((bucket_id = 'session-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) ;
drop policy if exists "Member updates own session media" on storage.objects; create policy "Member updates own session media" on storage.objects for UPDATE to authenticated using (((bucket_id = 'session-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text))) with check (((bucket_id = 'session-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists "Member uploads own progress photo" on storage.objects; create policy "Member uploads own progress photo" on storage.objects for INSERT to authenticated  with check (((bucket_id = 'progress-photos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists "Member uploads own session media" on storage.objects; create policy "Member uploads own session media" on storage.objects for INSERT to authenticated  with check (((bucket_id = 'session-media'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists "Members delete own videos" on storage.objects; create policy "Members delete own videos" on storage.objects for DELETE to public using (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]))) ;
drop policy if exists "Members read own technique videos" on storage.objects; create policy "Members read own technique videos" on storage.objects for SELECT to authenticated using (((bucket_id = 'technique-videos'::text) AND (((storage.foldername(name))[1] = (auth.uid())::text) OR has_role(auth.uid(), 'coach'::app_role)))) ;
drop policy if exists "Members upload own technique videos" on storage.objects; create policy "Members upload own technique videos" on storage.objects for INSERT to authenticated  with check (((bucket_id = 'technique-videos'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text)));
drop policy if exists "Members upload own videos" on storage.objects; create policy "Members upload own videos" on storage.objects for INSERT to public  with check (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists "Members view own videos" on storage.objects; create policy "Members view own videos" on storage.objects for SELECT to public using (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]))) ;
drop policy if exists technique_videos_delete_own on storage.objects; create policy technique_videos_delete_own on storage.objects for DELETE to authenticated using (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]))) ;
drop policy if exists technique_videos_insert_own on storage.objects; create policy technique_videos_insert_own on storage.objects for INSERT to authenticated  with check (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
drop policy if exists technique_videos_select_own_or_coach on storage.objects; create policy technique_videos_select_own_or_coach on storage.objects for SELECT to authenticated using (((bucket_id = 'technique-videos'::text) AND (((auth.uid())::text = (storage.foldername(name))[1]) OR has_role(auth.uid(), 'coach'::app_role)))) ;
drop policy if exists technique_videos_update_own on storage.objects; create policy technique_videos_update_own on storage.objects for UPDATE to authenticated using (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1]))) with check (((bucket_id = 'technique-videos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));

-- Métadonnées des objets (à rejouer APRÈS la copie des fichiers, ou à laisser
-- Supabase les recréer automatiquement à l'upload — dans ce cas, ignorer ce bloc).
commit;
